INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(28301, 'Philippians 3:13', 'Philippians', 3, 13, '&nbsp;زما وروڼو او خوېندو، زما دا خيال نۀ دے چې کمال ته رسېدلے يم خو زۀ اوس دا يو کار کول غواړم، چې هغه پخوانى څيزونه هېر کړم او د راتلونکو څيزونو دپاره سخت محنت وکړم،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28302, 'Philippians 3:14', 'Philippians', 3, 14, '&nbsp;زۀ د مقصد په طرف په منډه يم چې هغه انعام حاصل کړم د کوم دپاره چې زۀ خُدائ پاک د عيسىٰ مسيح په وسيله آسمانى ژوند ته بللے يم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28303, 'Philippians 3:15', 'Philippians', 3, 15, '&nbsp;مونږ ټول چې په روحانى توګه بالغان يُو په کار دى چې په هر خبره کښې يو شان خيال ولرو، او کۀ په څۀ خبره کښې ستاسو اختلاف وى نو دا خبره به هم خُدائ پاک تاسو ته ښکاره کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28304, 'Philippians 3:16', 'Philippians', 3, 16, '&nbsp;نو بيا دې مونږ په هغې خبرې کلک ودرېږو کومه چې مونږ حاصله کړې ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28305, 'Philippians 3:17', 'Philippians', 3, 17, '&nbsp;زما وروڼو او خوېندو، خپل ځان زما په شان کړئ، او د هغه خلقو نه زده کړئ څوک چې زمونږ په شان ژوند تېروى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28306, 'Philippians 3:18', 'Philippians', 3, 18, '&nbsp;ما تاسو ته په څو څو ځله د هغوئ په حقله وينا کړې ده، او اوس په اوښکو سره وايم چې ډېر خلق د مسيح د سولۍ د دشمنانو په شان ژوند تېروى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28307, 'Philippians 3:19', 'Philippians', 3, 19, '&nbsp;د هغوئ اَنجام هلاکت دے، د هغوئ خُدائ د هغوئ ګېډه ده، او هغوئ په خپلو شرمناک کارونو فخر کوى او د هغوئ سوچ په دُنياوى څيزونو دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28308, 'Philippians 3:20', 'Philippians', 3, 20, '&nbsp;خو مونږ د آسمان اوسېدونکى يُو او مونږ د آسمان نه د خلاصوونکى مالِک عيسىٰ مسيح د راتلو په اِنتظار کښې يُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28309, 'Philippians 3:21', 'Philippians', 3, 21, '&nbsp;هغه به زمونږ دا کمزورے بدن د خپل جلالى بدن هم شکل جوړ کړى د هم هغه قدرت په وسيله چې هغۀ پرې ټول څيزونه د خپل ځان تابع کړى دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28310, 'Philippians 4:1', 'Philippians', 4, 1, '&nbsp;نو ځکه زما خوږو وروڼو او خوېندو، تاسو سره چې زۀ مينه کوم او د ليدو مو خواهشمند يم، هم تاسو زما خوشحالى او تاج يئ، زما عزيزانو په دې طريقه په مالِک کښې قائم پاتې شئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28311, 'Philippians 4:2', 'Philippians', 4, 2, '&nbsp;زۀ يووديه او سنتخې ته مِنت کوم چې د مالِک په يووالى کښې په يو زړۀ پاتې شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28312, 'Philippians 4:3', 'Philippians', 4, 3, '&nbsp;او په خِدمت کښې زما وفادار ملګريه، زۀ تا ته هم خواست کوم چې تۀ د دغو ښځو مدد هم وکړه ځکه چې هغوئ ما سره په زېرى خورولو کښې لکه د کليمينتوس او زما د خِدمت نورو ملګرو سره خوارى وکړه د چا نومونه چې د ژوندون په کِتاب کښې ليکلى دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28313, 'Philippians 4:4', 'Philippians', 4, 4, '&nbsp;همېشه په مالِک کښې خوشحالى کوئ، او بيا هم وايم چې خوشحالى کوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28314, 'Philippians 4:5', 'Philippians', 4, 5, '&nbsp;پرېږده چې ټولو خلقو ته ستا نرم مزاجى ښکاره شى، ځکه چې مالِک اوس زر راتلونکے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28315, 'Philippians 4:6', 'Philippians', 4, 6, '&nbsp;د هيڅ خبرې غم مۀ کوئ بلکې په هره خبره کښې خپل درخواستونه د دُعا او زارۍ په وسيلې د شُکر ګزارۍ سره د خُدائ پاک په حضور کښې پېش کوئ،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28316, 'Philippians 4:7', 'Philippians', 4, 7, '&nbsp;نو بيا د خُدائ پاک سلامتى چې د پوهې نه بېخى بهر ده، هغه به ستاسو زړونه او خيالونه د عيسىٰ مسيح په وسيله محفوظ کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28317, 'Philippians 4:8', 'Philippians', 4, 8, '&nbsp;نو آخر دا چې، اے ګرانو وروڼو او خوېندو، څۀ چې رښتيا او د شرافت وى، څۀ چې حق او پاک وى، او څۀ چې زړۀ پورې وى، غرض دا څۀ چې اعلىٰ او د تعريف وى، په دې ټولو خبرو غور کوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28318, 'Philippians 4:9', 'Philippians', 4, 9, '&nbsp;او کومې خبرې چې تاسو ما نه زده کړې دى او حاصلې کړې دى او زما نه مو اورېدلې او ليدلې دى په هغې عمل کوئ، نو بيا به د سلامتۍ خُدائ پاک ستاسو مل وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28319, 'Philippians 4:10', 'Philippians', 4, 10, '&nbsp;زۀ په مالِک کښې ډېر خوشحاله يم چې آخر هم تاسو زما دپاره فکرمند شوئ، بې‌شکه چې اول هم تاسو فکرمند وئ خو موقع درته نۀ وه مِلاو شوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28320, 'Philippians 4:11', 'Philippians', 4, 11, '&nbsp;زۀ دا په دې وجه نۀ وايم چې زۀ محتاج يم، بلکې ما دا زده کړل چې څۀ چې ما سره دى په هغې راضى يم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28321, 'Philippians 4:12', 'Philippians', 4, 12, '&nbsp;زۀ هم په غريبۍ پوهېږم او هم په مالدارۍ. په هر حال کښې کۀ زۀ موړ يم يا کۀ اوږے، کۀ زۀ مالدار يم يا کۀ ضرورتمند ما د سکون ژوند تېرولو راز زده کړے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28322, 'Philippians 4:13', 'Philippians', 4, 13, '&nbsp;زۀ د مسيح په وسيله هر څۀ کولے شم څوک چې ما له طاقت راکوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28323, 'Philippians 4:14', 'Philippians', 4, 14, '&nbsp;خو دا هم ستاسو مهربانى ده چې زما په مصيبت کښې شريک شوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28324, 'Philippians 4:15', 'Philippians', 4, 15, '&nbsp;اے فيليپيانو، تاسو په خپله خبر يئ چې د زيرى په وړومبو ورځو کښې کله چې زۀ د مِکدونيه نه روان شوم نو ستاسو نه سېوا يو جماعت هم د ورکړې راکړې په معامله کښې زما مدد ونۀ کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28325, 'Philippians 4:16', 'Philippians', 4, 16, '&nbsp;ځکه کله چې زۀ په تِسالونيکيه کښې وم نو تاسو ما ته د يو ځل نه زيات زما د حاجتونو د پوره کولو دپاره مدد رالېږلے وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28326, 'Philippians 4:17', 'Philippians', 4, 17, '&nbsp;زۀ دا خبره د انعام غوښتلو دپاره نۀ کوم بلکې د دې دپاره يې کوم چې ستاسو حساب کِتاب ته فائده ورسى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28327, 'Philippians 4:18', 'Philippians', 4, 18, '&nbsp;ما سره هر څۀ شته او د ضرورت نه راسره زيات دى، او چې ستاسو رالېږلې ډالۍ مې د اِپفروديتوس نه واخستلې نو مطمئن شوم. دا هغه د خوشبويۍ نذرانه او قبوله قربانى ده چې د خُدائ پاک خوښه ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28328, 'Philippians 4:19', 'Philippians', 4, 19, '&nbsp;او زما خُدائ پاک به ستاسو هر حاجت د خپل جلالى دولت په مطابق د عيسىٰ مسيح په وسيله پوره کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28329, 'Philippians 4:20', 'Philippians', 4, 20, '&nbsp;زمونږ د خُدائ پاک او پلار جلال دې تل تر تله وى. آمين.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28330, 'Philippians 4:21', 'Philippians', 4, 21, '&nbsp;ټولو مقدسينو ته په عيسىٰ مسيح کښې سلام وايم، او کوم وروڼه چې ما سره دى هغوئ تاسو ته هم سلام وائى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28331, 'Philippians 4:22', 'Philippians', 4, 22, '&nbsp;ټول مقدسين خصوصاً د قيصر د خاندان خلق تاسو ته سلام وائى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28332, 'Philippians 4:23', 'Philippians', 4, 23, '&nbsp;زمونږ د مالِک عيسىٰ مسيح فضل دې تاسو ټولو سره مل وى. آمين.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28333, 'Colossians 1:1', 'Colossians', 1, 1, '&nbsp;دا خط د پولوس د طرف نه چې د خُدائ پاک په رضا د عيسىٰ مسيح رسول دے او زمونږ د ورور تيموتيوس د طرف نه،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28334, 'Colossians 1:2', 'Colossians', 1, 2, '&nbsp;او په مسيح کښې هغه ايماندارانو او وفادارو وروڼو او خوېندو ته چې په کولوسى کښې دى. زمونږ د خُدائ پلار د طرف نه دې په تاسو فضل او سلامتى وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28335, 'Colossians 1:3', 'Colossians', 1, 3, '&nbsp;چې کله مونږ ستاسو دپاره دُعا کوُو نو مونږ د خُدائ پاک، يعنې د مالِک عيسىٰ مسيح د پلار شُکر کوُو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28336, 'Colossians 1:4', 'Colossians', 1, 4, '&nbsp;ځکه چې مونږ اورېدلى دى چې ستاسو په عيسىٰ مسيح ايمان دے او د ټولو مقدسينو سره مينه کوئ،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28337, 'Colossians 1:5', 'Colossians', 1, 5, '&nbsp;ستاسو د هغه اُميد په وجه کوم چې په آسمان کښې ستاسو انتظار کوى. تاسو د وړاندې نه د دې اُميد په حقله په رښتينى کلام يعنې زېرى کښې اورېدلى دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28338, 'Colossians 1:6', 'Colossians', 1, 6, '&nbsp;هم دغه زيرے چې تاسو ته راورسېدو، په ټوله دُنيا کښې خوريږى او مېوه نيسى. لکه څنګه چې يې ستاسو په مينځ کښې هم مېوه ونيوله د هغه ورځې نه چې تاسو د اول ځل دپاره دا زيرے واورېدو او د خُدائ پاک د فضل په حقله په حقيقت پوهه شوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28339, 'Colossians 1:7', 'Colossians', 1, 7, '&nbsp;تاسو زمونږ د خوږ خادِم اِپفراس نه څوک چې په خِدمت کښې مونږ سره شريک دے زده کړل. هغه د مسيح وفادار خادِم دے، او هغه ستاسو په ځائ زمونږ مدد کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28340, 'Colossians 1:8', 'Colossians', 1, 8, '&nbsp;هغۀ مونږ ته ستاسو د هغه مينې په حقله ووئيل چې تاسو ته روحُ القُدس درکړې ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28341, 'Colossians 1:9', 'Colossians', 1, 9, '&nbsp;نو بيا د کومې ورځې نه چې مونږ په اول ځل ستاسو په حقله واورېدل، نو مونږ ستاسو دپاره دُعا نۀ ده بنده کړى. او د خُدائ پاک نه دا خواست کوُو چې هغه دې تاسو ته د خپلې مرضۍ پوره عِلم او روحانى پوهه او حکمت درکړى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28342, 'Colossians 1:10', 'Colossians', 1, 10, '&nbsp;د دې دپاره چې تاسو د مالِک لائق ژوند تير کړئ او په هره طريقه هغه راضى کړئ او په هر نېک کار کښې مېوه ونيسئ او د خُدائ پاک په عِلم کښې ترقى وکړئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28343, 'Colossians 1:11', 'Colossians', 1, 11, '&nbsp;او زمونږ دا دُعا ده چې تاسو دې د هغۀ په ټول جلالى قدرت سره مضبوط شئ چې په تاسو کښې دې لوئ زغم او صبر پېدا شى. او تاسو دې په خوشحالۍ معمور شئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28344, 'Colossians 1:12', 'Colossians', 1, 12, '&nbsp;د پلار شُکر ادا کوئ چا چې تاسو د دې جوګه کړئ چې د مقدسينو سره يې د نُور د بادشاهۍ په وراثت کښې شريک کړئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28345, 'Colossians 1:13', 'Colossians', 1, 13, '&nbsp;هغۀ مونږ د تيارې د بادشاهۍ د اختيار نه آزاد کړُو او د خپل محبوب زوئ په بادشاهۍ کښې يې داخل کړُو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28346, 'Colossians 1:14', 'Colossians', 1, 14, '&nbsp;چا کښې چې مونږ ته خلاصون، يعنې د ګناهونو نه معافى حاصله ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28347, 'Colossians 1:15', 'Colossians', 1, 15, '&nbsp;مسيح د ناليدلى خُدائ پاک صورت او د ټولو مخلوقاتو نه اول پېدا شوے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28348, 'Colossians 1:16', 'Colossians', 1, 16, '&nbsp;ځکه چې د هغۀ په وسيله ټول څيزونه پېدا شول چې په آسمان کښې دى يا په زمکه، ليدونکى دى يا ناليدونکى دى، تختونه دى کۀ رياستونه کۀ حکومتونه يا اختيارات دى، هر څۀ د مسيح په وسيله او د هغۀ دپاره پېدا شُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28349, 'Colossians 1:17', 'Colossians', 1, 17, '&nbsp;او هغه په خپله د ټولو څيزونو نه اول پېدا شوے دے او ټول څيزونه په خپله يو ځائ قائم ساتى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28350, 'Colossians 1:18', 'Colossians', 1, 18, '&nbsp;او هغه د بدن، يعنې د جماعت سر دے، هغه ازل دے، او د مړو نه اول ژوندے شوے دے د دې دپاره چې په هر څۀ کښې د هغۀ درجه اول وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28351, 'Colossians 1:19', 'Colossians', 1, 19, '&nbsp;ځکه چې د خُدائ پاک دا خوښه وه چې د هغۀ ټول الوهيت دې په مسيح کښې وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28352, 'Colossians 1:20', 'Colossians', 1, 20, '&nbsp;او د هغۀ په وسيله خُدائ پاک راضى شو چې هر څۀ د ځان سره پخلا کړى هغه کۀ په زمکه وى او کۀ په آسمان کښې او هغۀ د مسيح د وينې په وسيله امن راوستو چې په سولۍ تويه شوې ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28353, 'Colossians 1:21', 'Colossians', 1, 21, '&nbsp;يو وخت تاسو پخپله هم د خُدائ پاک نه لرې وئ او د خپلو سوچونو او بدو اخلاقو په وجه د هغۀ مخالفين وئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28354, 'Colossians 1:22', 'Colossians', 1, 22, '&nbsp;خو اوس د مسيح د جسمانى مرګ په وسيله تاسو د هغۀ سره پخلا شوئ د دې دپاره چې هغه تاسو د هغۀ په حضور کښې مقدس، بې‌داغه او بې‌اِلزامه حاضر کړى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28355, 'Colossians 1:23', 'Colossians', 1, 23, '&nbsp;کۀ تاسو د ايمان په بنياد مضبوط او ټينګ پاتې شئ او هغه اُميد پرې نۀ ږدئ کوم چې د زيرى په اورېدو ستاسو په زړونو کښې پېدا شوے دے. هغه زيرے چې ټولې دُنيا ته واورولے شو، او زۀ پولوس هم د دغه زېرى خادِم شوم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28356, 'Colossians 1:24', 'Colossians', 1, 24, '&nbsp;زۀ اوس په هغه کړاونو کښې خوشحاله يم کوم چې ستاسو دپاره تېروم. ځکه چې زۀ په خپل بدن کښې د مسيح د بدن يعنې د جماعت دپاره د مسيح د کړاونو هغه کمے پوره کوم، کوم چې لا تر اوسه پورې پاتې دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28357, 'Colossians 1:25', 'Colossians', 1, 25, '&nbsp;د خُدائ پاک د هغه اِنتظام په مطابق زۀ د جماعت خادِم شوم چې ما ته ستاسو دپاره راکړے شوے دے، د دې دپاره چې زۀ تاسو ته د خُدائ پاک کلام پوره پوره بيان کړم،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28358, 'Colossians 1:26', 'Colossians', 1, 26, '&nbsp;يعنې هغه راز کوم چې د زمانو او پيړو راسې پټ وو خو اوس دا مقدسينو ته څرګند شوے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28359, 'Colossians 1:27', 'Colossians', 1, 27, '&nbsp;خُدائ پاک غوښتل چې تاسو غېر‌يهوديانو ته هم دا بې‌حده شاندار او قيمتى راز ښکاره کړى، او هغه راز دا دے چې مسيح په تاسو کښې دے او هغه د راتلونکى جلال اُميد دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28360, 'Colossians 1:28', 'Colossians', 1, 28, '&nbsp;نو چې مونږ د هغۀ زيرے بيان کړُو او هر چا ته نصيحت وکړُو او هر يو ته په پوره هوښيارتيا سره تعليم ورکړُو نو چې هر څوک مونږ په مسيح کښې خُدائ پاک ته بالغ پېش کړُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28361, 'Colossians 1:29', 'Colossians', 1, 29, '&nbsp;د دې دپاره زۀ د مسيح د هغه قوت په مطابق د زړۀ نه خوارى کوم چې په ما کښې په زور اثر کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28362, 'Colossians 2:1', 'Colossians', 2, 1, '&nbsp;زۀ غواړم چې تاسو پوهه شئ چې زۀ ستاسو دپاره او د لوديکيانو د جماعت دپاره او د هغوئ ټولو دپاره چا چې زۀ مخامخ نۀ يم ليدلے، څومره خوارى کوم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28363, 'Colossians 2:2', 'Colossians', 2, 2, '&nbsp;زۀ غواړم چې هغوئ زړَور شى او د مينې په تار د يو بل سره وګنډلے شى، د دې دپاره چې هغوئ پخپله پوهه پوره اعتماد ولرى او د خُدائ پاک د هغه راز په منصوبه پوهه شى، کوم چې مسيح په خپله دے،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28364, 'Colossians 2:3', 'Colossians', 2, 3, '&nbsp;په چا کښې چې د حِکمت او عِلم ټولې خزانې پټې پرتې دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28365, 'Colossians 2:4', 'Colossians', 2, 4, '&nbsp;دا زۀ تاسو ته د دې دپاره وايم چې څوک تاسو په دروغژن بحثونو دوکه نۀ کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28366, 'Colossians 2:5', 'Colossians', 2, 5, '&nbsp;کۀ څۀ هم چې زۀ اوس ستاسو نه لرې يم خو په روح کښې تاسو سره يم، او زۀ په دې خوشحاله يم چې تاسو وګورم چې څومره په ښې طريقې سره ژوند تېروئ او په مسيح باندې ستاسو ايمان پوخ او مضبوط دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28367, 'Colossians 2:6', 'Colossians', 2, 6, '&nbsp;نو بيا څنګه چې تاسو عيسىٰ مسيح د خپل مالِک په توګه قبول کړو، نو هم هغه شان په هغۀ کښې ژوند تېروئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28368, 'Colossians 2:7', 'Colossians', 2, 7, '&nbsp;په هغۀ کښې جرړې خورې کړئ او خپل ژوند په هغۀ باندې آباد کړئ، او په ايمان کښې مضبوط شئ څنګه چې تاسو ته تعليم درکړے شوے وو او شُکر ادا کوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28369, 'Colossians 2:8', 'Colossians', 2, 8, '&nbsp;خيال کوئ هسې نه چې څوک مو په تشو فلسفو او دوکه مارو خبرو کښې راګېر کړى، ځکه چې د هغوئ خبرې د انسانى رواياتو او د دُنيا د بنيادى اصُولو په مطابق دى او د مسيح په مطابق نۀ دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28370, 'Colossians 2:9', 'Colossians', 2, 9, '&nbsp;ځکه چې په مسيح کښې الوهيت په مکمل توګه مجسم شوے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28371, 'Colossians 2:10', 'Colossians', 2, 10, '&nbsp;او تاسو په مسيح کښې معمور شوى يئ څوک چې د هر حاکِم او اختيار سر دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28372, 'Colossians 2:11', 'Colossians', 2, 11, '&nbsp;کله چې تاسو په مسيح ايمان راوړو نو تاسو په جسمانى توګه سنت شوى نۀ وئ. مسيح تاسو په روحانى توګه سنت کړئ او ستاسو د ګناه فطرت يې ختم کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28373, 'Colossians 2:12', 'Colossians', 2, 12, '&nbsp;تاسو د مسيح سره په بپتسمه کښې ښخ شوئ او د ايمان په وسيله د خُدائ پاک په قدرت کښې هم تاسو د هغۀ سره بيا راژوندى شوئ چا چې هغه د مړو نه راپاڅولے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28374, 'Colossians 2:13', 'Colossians', 2, 13, '&nbsp;تاسو د خپلو نافرمانو په وجه مړۀ وئ ځکه چې ستاسو د ګناه فطرت ختم شوے نۀ وو. نو بيا خُدائ پاک تاسو د مسيح سره راژوندى کړئ، ځکه چې هغۀ ستاسو ټولې نافرمانۍ معاف کړې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28375, 'Colossians 2:14', 'Colossians', 2, 14, '&nbsp;هغه څۀ چې د شريعت په مطابق زمونږ خلاف جرم وو هغۀ هغه ټول ريکارډ ختم کړو. هغه يې يو خوا ته کړل او په سولۍ يې مېخ کړل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28376, 'Colossians 2:15', 'Colossians', 2, 15, '&nbsp;دغه شان هغۀ د روحانى حاکمانو او د اختيار د خاوندانو نه وسلې واخستلې، او هغوئ يې په خلقو کښې رسوا کړل او د سولۍ په وسيله يې په هغوئ کاميابى حاصله کړه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28377, 'Colossians 2:16', 'Colossians', 2, 16, '&nbsp;نو په دې وجه څوک مۀ پرېږدئ چې په تاسو د خوراک څښاک يا د اختر يا د نوې مياشت يا د سبت د ورځې په معامله کښې اِلزام ولګوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28378, 'Colossians 2:17', 'Colossians', 2, 17, '&nbsp;ځکه چې دا صرف د راتلونکو څيزونو سورے دے خو حقيقت په مسيح کښې دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28379, 'Colossians 2:18', 'Colossians', 2, 18, '&nbsp;چا ته هم وخت مۀ ورکوئ چې خپل ځان دې ښۀ وګڼى او تاسو دې مجرم کړى. هغوئ خپل ځان په ظاهرى عاجزى ښودلو سره او د فرښتو په عبادت کولو او د روياګانو د ليدو په تفصيلى بيان سره نور خلق مجبوروى. او د هغوئ غېر روحانى ذهن هغوئ پړسولى دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28380, 'Colossians 2:19', 'Colossians', 2, 19, '&nbsp;او هغوئ د بدن د سر يعنې مسيح سره تعلق پرېښے دے. ځکه چې په هغۀ کښې د بدن ټول بندونه او پلې په خپلو کښې يو ځائ کيږى او خُدائ پاک ورله وده ورکوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28381, 'Colossians 2:20', 'Colossians', 2, 20, '&nbsp;نو چې تاسو د مسيح سره مړۀ شوئ او هغۀ تاسو د دُنيا د بنيادى اصُولو نه آزاد کړئ، نو بيا تاسو ولې په دُنياوى اصُولو ژوند تېروئ؟ او د هغې حُکمونه داسې منئ چې،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28382, 'Colossians 2:21', 'Colossians', 2, 21, '&nbsp;”دې ته لاس مۀ وروړئ، دا مۀ څکئ، مۀ ورسره لګئ؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28383, 'Colossians 2:22', 'Colossians', 2, 22, '&nbsp;خو د دغه څيزونو په حقله حُکمونه صرف انسانى تعليمونه دى چې په استعمالولو کښې به ختم شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28384, 'Colossians 2:23', 'Colossians', 2, 23, '&nbsp;داسې حُکمونه خو په ظاهره عقلمند ښکارى هغه دا چې د خپلې مرضۍ په مطابق سخت عبادت او دروغژنه عاجزى او د فقيرانو په شان ژوند تېرول، خو دا د انسان په نفسانى شوقونو قابو نۀ شى راوستلے او بې‌فائدې دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28385, 'Colossians 3:1', 'Colossians', 3, 1, '&nbsp;نو تاسو چې د مسيح سره بيا راژوندى شوئ نو تاسو بره د آسمانى څيزونو لټون کوئ، چرته چې مسيح د خُدائ پاک ښى لاس ته ناست دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28386, 'Colossians 3:2', 'Colossians', 3, 2, '&nbsp;د آسمانى څيزونو په حقله سوچ کوئ او د دُنياوى څيزونو په حقله سوچ مۀ کوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28387, 'Colossians 3:3', 'Colossians', 3, 3, '&nbsp;ځکه چې تاسو مړۀ شوى يئ خو ستاسو ژوند د مسيح سره په خُدائ پاک کښې پټ دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28388, 'Colossians 3:4', 'Colossians', 3, 4, '&nbsp;کله چې مسيح څوک چې ستاسو ژوندون دے راښکاره شى نو تاسو به هم د هغۀ سره په جلال کښې ښکاره شئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28389, 'Colossians 3:5', 'Colossians', 3, 5, '&nbsp;نو هم په دې وجه هر هغه خواهش مړ کړئ کوم چې ستاسو دُنياوى فطرت سره تعلق ساتى لکه زناکارى، پليتى، شهوت پرستى، بد خواهشات او حرص چې بُت پرستى ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
