(28392, 'Colossians 3:8', 'Colossians', 3, 8, '&nbsp;خو اوس تاسو له په کار دى چې د غصې، قهر، بدخواهۍ، چُغلۍ او سپکې خبرې پرېږدئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28393, 'Colossians 3:9', 'Colossians', 3, 9, '&nbsp;يو بل ته دروغ مۀ وايئ ځکه چې تاسو خپل زوړ د ګناه فطرت د دې د عملونو سره اخوا کړو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28394, 'Colossians 3:10', 'Colossians', 3, 10, '&nbsp;تاسو نوے فطرت خپل کړئ، او داسې نوى شئ لکه څنګه چې تاسو د خپل خالق په حقله معرفت حاصل کړو او ورسره ورسره د هغۀ په شان شئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28395, 'Colossians 3:11', 'Colossians', 3, 11, '&nbsp;په دې نوى ژوند کښې نۀ يهودى پاتې شو، نۀ غېر يهودى، نۀ سنت شوى، نۀ ناسنته، نۀ بهرنى، نۀ وحشى، نۀ غلام او نۀ آزاد، بلکې مسيح په تاسو ټولو کښې هر څۀ دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28396, 'Colossians 3:12', 'Colossians', 3, 12, '&nbsp;نو بيا چې خُدائ پاک تاسو غوره او مقدس وګرځولئ او درسره يې مينه وکړه نو بيا د زړۀ سواندۍ، مهربانۍ، شرافت، عاجزۍ، او صبر جامې واغوندئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28397, 'Colossians 3:13', 'Colossians', 3, 13, '&nbsp;يو بل برداشت کوئ، او کۀ د يو بل خلاف مو څۀ شکايت وى نو هغه داسې معاف کړئ لکه څنګه چې تاسو مالِک معاف کړئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28398, 'Colossians 3:14', 'Colossians', 3, 14, '&nbsp;او د دې هر څۀ نه بغېر تاسو په خپلو کښې د مينې جامې واغوندئ چې هغه هر څۀ په پوره يووالى سره په خپلو کښې يوځائ کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28399, 'Colossians 3:15', 'Colossians', 3, 15, '&nbsp;نو د مسيح سلامتى دې ستاسو په زړونو حکومت وکړى ځکه چې تاسو د يو بدن د اندامونو په طور د سلامتۍ دپاره رابللے شوى يئ. او شُکر ګزارى هم کوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28400, 'Colossians 3:16', 'Colossians', 3, 16, '&nbsp;د مسيح کلام دې ستاسو په زړونو کښې ډېر ځائ ومومى، او په خپلو کښې يو بل له پوره حکمت سره تعليم ورکوئ او نصيحت کوئ، او په خپلو زړونو کښې د شُکر ګزارۍ سره د خُدائ پاک ثناء، زبور او روحانى سندرې وايئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');